def image(file,alt,w=600):return f'<img src="assets/{file}" width="{w}" alt="{escape(alt)}" style="display:block;border:0;width:100%;max-width:{w}px;height:auto;">'
def linked(file,alt,url,w=600):return f'<a href="{url}" target="_blank" style="text-decoration:none;">{image(file,alt,w)}</a>'
def label(t):return f'<p style="margin:0 0 12px;color:#c6a7a7;font:700 10px/16px Arial,sans-serif;letter-spacing:1.8px;">{t}</p>'
def heading(t,size=28):return f'<h2 class="headline" style="margin:0 0 16px;color:white;font:700 {size}px/{size+4}px Arial,sans-serif;letter-spacing:-.7px;">{t}</h2>'
def text(t):return f'<p style="margin:0 0 22px;color:{GRAY};font:14px/21px Arial,sans-serif;">{t}</p>'
def button(t,u):return f'<table role="presentation" cellpadding="0" cellspacing="0" align="center"><tr><td align="center" bgcolor="#ffffff" style="background:#ffffff;mso-padding-alt:14px 19px;"><a href="{u}" target="_blank" style="display:inline-block;background:#ffffff;border:1px solid #ffffff;padding:14px 19px;font:700 11px/18px Arial,sans-serif;letter-spacing:1.5px;color:#080808;text-decoration:none;mso-padding-alt:0;">{t}</a></td></tr></table>'
def row(t,bg=BLACK,pad='28px 30px'):return f'<tr><td class="pad" bgcolor="{bg}" style="padding:{pad};background:{bg};">{t}</td></tr>'
def split(photo,alt,title,copy,cta,url,flip=False,tag='',stat=''):
 media=f'<td class="stack media" width="300" valign="top" bgcolor="{CHARCOAL}" style="background:{CHARCOAL};width:300px;">'+linked(photo,alt,url,300)
 if stat:media+=f'<p style="margin:0;padding:22px 18px;color:#ffffff;font:700 23px/28px Arial,sans-serif;text-align:center;">{stat}</p>'
 media+='</td>'
 content=f'<td class="stack copy" width="300" valign="middle" bgcolor="{BLACK}" style="width:300px;background:{BLACK};"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td class="copy-inner" style="padding:26px 25px;">'+(label(tag) if tag else '')+heading(title)+text(copy)+button(cta,url)+'</td></tr></table></td>'
 return '<tr><td><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="table-layout:fixed;"><tr>'+((content+media) if flip else(media+content))+'</tr></table></td></tr>'
